/**
 * กฎของด่านตรวจ PR — ฟังก์ชันล้วน รับข้อเท็จจริงเข้า คืนรายการปัญหาออก
 *
 * ── ทำไมแยกออกมาจาก YAML ────────────────────────────────────────
 * ตรรกะที่ฝังอยู่ใน YAML ของ workflow **เทสเรียกไม่ได้** ยืนยันได้ทางเดียวคือ
 * เปิด PR จริงแล้วดูว่ามันแดงไหม ซึ่งพิสูจน์อะไรให้ PR รอบถัดไปไม่ได้เลย
 * `plan` เคยพลาดรูปแบบนี้สี่รอบติดกับด่าน vendor เมื่อ 30 ส.ค. 2026
 * จนต้องแยกสคริปต์ออกมา — repo นี้เริ่มจากตรงนั้นเลย ไม่ต้องรอพลาดก่อน
 *
 * ไฟล์นี้ไม่แตะ git ไม่แตะไฟล์ ไม่แตะเครือข่าย (หลักเดียวกับ INVARIANTS C1)
 * ตัวที่ไปคุยกับ git คือ `guard.mjs` · เทสอยู่ที่ `tests/guard.test.mjs`
 * ซึ่งรันด้วย `npm test` ทุก PR อยู่แล้ว
 *
 * ⚠️ PR ที่แก้ไฟล์นี้ = PR ที่แก้ด่านตรวจเอง · กฎข้อ 1 จะตะโกนให้เจ้าของอ่านด้วยตา
 */

/** ไฟล์ที่ถูกส่งไปถึงเบราว์เซอร์ของพนักงาน — ใช้นับขนาด PR และด่านบัมป์เลขรุ่น
 *
 *  `lib/**` ถูกกันไว้ล่วงหน้าเผื่อวันหนึ่งเลิกใช้ CDN แล้วเอาไลบรารีมาไว้ใน repo
 *  ไลบรารีมีบรรทัดเดียวยาวเป็นแสนตัวอักษร ถ้านับรวมเข้าเพดานขนาด PR
 *  ด่านจะแดงทุกใบที่แตะมันโดยไม่ได้บอกอะไรที่มีประโยชน์
 *  (แต่ด่านบัมป์เลขรุ่น **ต้องนับ** — ดู VERSIONED_PATHSPEC)
 */
export const APP_PATHSPEC = ['*.html', '*.js', '*.mjs',
  ':(exclude)tests/**', ':(exclude).github/**', ':(exclude)lib/**'];

/** ไฟล์ที่เปลี่ยนแล้วเครื่องของพนักงานต้องโหลดใหม่ = ต้องบัมป์ app-version (F4 ของ plan)
 *  ต่างจาก APP_PATHSPEC ที่ **รวม lib/** เพราะเปลี่ยนไลบรารีคือของที่ต้องโหลดใหม่ที่สุด */
export const VERSIONED_PATHSPEC = ['*.html', '*.js', '*.mjs',
  ':(exclude)tests/**', ':(exclude).github/**'];

/** เพดานขนาด PR ของ agent — นับบรรทัดที่เพิ่ม+ลบในไฟล์แอป
 *  80 คือจุดที่ควรหยุดถามเจ้าของ (เขียนไว้ใน CLAUDE.md) · 150 คือจุดที่เลยเถิดแล้ว
 *  คำสั่งใน CLAUDE.md เป็นสิ่งที่ agent เลือกไม่ทำตามได้ ตัวเลขนี้คือเส้นที่เลือกไม่ได้ */
export const APP_LINE_LIMIT = 150;

/** ของที่ห้ามหลุดเข้า repo public — ตรวจเฉพาะบรรทัดที่ "เพิ่มเข้ามา" */
export const SECRET_PATTERNS = [
  [/AKfyc[A-Za-z0-9_-]{20,}/, 'URL ของ Apps Script deployment'],
  [/gh[pousr]_[A-Za-z0-9]{30,}/, 'GitHub token'],
  [/github_pat_[A-Za-z0-9_]{30,}/, 'GitHub PAT'],
  [/sk-ant-[A-Za-z0-9_-]{20,}/, 'Anthropic API key'],
  [/AIza[A-Za-z0-9_-]{30,}/, 'Google API key'],
];

/** รหัส PO ตัวจริงของบริษัท — `TM` + 3 หลัก + เดือน(3-9 A B) + นิติบุคคล(H U T A) + ท้าย
 *
 *  ⚠️ **ข้อนี้ไม่ใช่ทฤษฎี** — 10 ต.ค. 2026 รหัส PO จริงเกือบหลุดเข้าเทสของ repo นี้
 *     จับได้ตอนกวาดก่อน push พอดี ของแบบนั้นต้องมีเครื่องจับ ไม่ใช่ต้องระวังให้มากขึ้น
 *
 *  ตัวอย่างในโค้ด เทส และเอกสาร **ให้ขึ้นต้นด้วย ZZ หรือ XX** ห้ามใช้ TM
 *  เพราะคนอ่านแยกไม่ออกว่ารหัสไหนสมมติ รหัสไหนของจริง และ repo นี้เป็น public
 */
export const REAL_PO_RE = /\bTM\d{3}[0-9AB][HUTA][A-Z0-9]{2,4}\b/;

/** ไฟล์ที่เป็นข้อมูลธุรกิจเกือบแน่นอน — ฟอร์มจริง ตารางที่ export มา รูปจากหน้างาน
 *  `.gitignore` แบบปฏิเสธทุกอย่างกันไว้ชั้นหนึ่งแล้ว แต่ `git add -f` ข้ามได้
 *  ด่านนี้คือชั้นที่ข้ามไม่ได้ เพราะเป็น required check */
export const DATA_FILE_RE = /\.(xlsx?|xlsm|csv|pdf|jpe?g|png|zip)$/i;

/** โดเมนที่อนุญาตให้โหลดไลบรารีจากเน็ตได้
 *
 *  ต่างจาก `plan` ที่ห้ามโหลดจากเน็ตทุกกรณี เพราะ `plan` ต้องใช้ได้ตอนเน็ตหลุดในโรงงาน
 *  แอปนี้ไม่มีข้อมูลให้ดูเลยถ้าไม่มีเน็ต (INVARIANTS B1) จึงยอมให้ใช้ CDN ได้
 *  แต่ต้อง **ปักรุ่นเป๊ะ** — URL แบบ `vue@3` เปลี่ยนของใต้เท้าเราได้เองเงียบ ๆ
 *  แล้ววันที่หน้าจอเพี้ยนจะไม่มี commit ไหนอธิบายได้เลยว่าเกิดจากอะไร
 */
export const ALLOWED_CDN_HOSTS = ['cdnjs.cloudflare.com'];

/** ทางที่ดึงของจากเน็ตเข้ามาได้ — `"?` ทำให้จับแบบไม่ใส่อัญประกาศได้ด้วย */
const NET_LOAD_RE = /(?:<script[^>]+src="?|<link[^>]+href="?|from "|import\("|importScripts\(")(https?:\/\/[^"'\s>]+)/g;

/** เลขรุ่นที่ปักแน่น เช่น 3.4.21 — `vue@3` หรือ `/latest/` ไม่นับ */
const PINNED_RE = /\d+\.\d+\.\d+/;

const txt = v => String(v == null ? '' : v);

/** เลขรุ่นที่ประกาศไว้ใน <head> ของหน้าเว็บ · '' = ไม่มี */
export function appVersionOf(html) {
  const m = /<meta\s+name="app-version"\s+content="([^"]*)"/.exec(txt(html));
  return m ? m[1].trim() : '';
}

/**
 * ด่านบัมป์เลขรุ่น — แก้ไฟล์ที่ส่งไปถึงเบราว์เซอร์แล้วต้องเปลี่ยนเลขรุ่นด้วย
 *
 * เครื่องที่ค้างไฟล์เก่าไว้ไม่มีทางรู้ว่ามีของใหม่ และเลขบนหน้าจอจะกลายเป็นคำโกหก
 * ซึ่งอันตรายกว่าไม่มีเลขเลย เพราะทุกคนจะเชื่อมัน (กฎเดียวกับ F4 ของ `plan`)
 *
 * ⚠️ repo นี้แยกเป็นหลายไฟล์ตั้งแต่ต้น — แก้แค่ `core/*.js` ก็ต้องบัมป์
 *    ไม่งั้นเครื่องจะเอา core/ ใหม่ไปคู่กับ index.html เก่า ซึ่งพังเงียบกว่าเดิม
 *    เพราะแต่ละไฟล์หมดอายุแคชไม่พร้อมกัน
 */
export function checkVersionBump(facts) {
  const f = facts || {};
  const errors = [];
  if (!(f.changedVersioned || []).length) return { errors, skipped: true };

  // เลขรุ่นประกาศที่ไฟล์ .html ที่รากไฟล์เดียว ถ้าวันหนึ่งมีสองแอปในรากเดียวกัน
  // ด่านนี้ต้องถูกเขียนใหม่ — ให้มันแดงเองตอนนั้นดีกว่าเดาเงียบ ๆ ว่าไฟล์ไหนคือแอปหลัก
  if (Number(f.htmlCount) !== 1) {
    errors.push(`รากของ repo มีไฟล์ .html ${f.htmlCount} ไฟล์ — ` +
      'ด่านนี้เขียนไว้สำหรับแอปเดียว ต้องแก้ด่านก่อนเพิ่มแอปที่สอง');
    return { errors };
  }
  if (!f.newVersion) {
    errors.push('ไม่พบ <meta name="app-version"> ในไฟล์ — ' +
      'ผู้ใช้จะบอกไม่ได้ว่าเครื่องตัวเองรันรุ่นไหน');
  } else if (f.oldVersion === f.newVersion) {
    errors.push(`PR นี้แก้ไฟล์ที่เบราว์เซอร์โหลด แต่ไม่ได้บัมป์ app-version (ยังเป็น ${f.newVersion}) — ` +
      'เครื่องที่ค้างไฟล์เก่าไว้จะไม่รู้ว่ามีของใหม่');
  }
  return { errors };
}

/**
 * แยกบรรทัดที่เพิ่มเข้ามาออกจาก unified diff พร้อมบอกว่ามาจากไฟล์ไหน
 *
 * ⚠️ ต้องรู้ว่าบรรทัดมาจากไฟล์ไหน ไม่ใช่กองรวมกัน — ไม่งั้นแยกไม่ออกว่า
 *    รหัสที่เจอมาจากไฟล์เทส (ต้องห้าม) หรือจากเอกสารที่อธิบายรูปแบบรหัส
 *    และข้อความ error ที่บอกไฟล์ได้ ทำให้คนแก้ไม่ต้องไปไล่หาเอง
 */
export function parseAddedLines(diffText) {
  const out = [];
  let file = '';
  for (const raw of txt(diffText).split(/\r?\n/)) {
    const m = /^\+\+\+ b\/(.*)$/.exec(raw);
    if (m) { file = m[1]; continue; }
    if (/^diff --git /.test(raw)) { file = ''; continue; }
    // `+++` ถูกจับไปแล้วข้างบน ที่เหลือที่ขึ้นต้น + คือเนื้อหาที่เพิ่มเข้ามา
    if (raw.startsWith('+') && file) out.push({ file, text: raw.slice(1) });
  }
  return out;
}

/** URL ที่โหลดของจากเน็ตในบรรทัดนี้ (คืนทุกตัวที่เจอ) */
export function netLoadUrls(line) {
  // อัญประกาศเดี่ยวแปลงเป็นคู่ก่อน รูปแบบเดียวจึงจับได้ทั้งสองแบบ
  const s = txt(line).replace(/'/g, '"');
  const urls = [];
  for (const m of s.matchAll(NET_LOAD_RE)) urls.push(m[1]);
  return urls;
}

/** โฮสต์ของ URL โดยไม่ใช้ตัวแยก URL ของ node (บรรทัดใน diff ไม่ใช่ URL ที่สะอาด) */
const hostOf = url => (/^https?:\/\/([^/"'\s>]+)/.exec(txt(url)) || [, ''])[1];

/** ไฟล์ที่เบราว์เซอร์ของพนักงานโหลดจริง — เทสกับ workflow ไม่นับ
 *  ต้องตรงกับแนวคิดเดียวกับ APP_PATHSPEC ข้างบน (git ใช้ pathspec · ที่นี่ใช้ชื่อไฟล์) */
export const isBrowserFile = p =>
  /\.(html|js|mjs)$/i.test(txt(p)) && !/^(tests|\.github)\//.test(txt(p));

/**
 * ตรวจทั้งหมด — คืน { errors, warnings } เป็นข้อความภาษาไทยพร้อมส่งให้คนอ่าน
 *
 * facts
 *   changed   รายชื่อไฟล์ที่เปลี่ยน (เพิ่ม/แก้/ลบ)
 *   deleted   รายชื่อไฟล์ที่ถูกลบ
 *   added     [{file, text}] บรรทัดที่เพิ่มเข้ามา (จาก parseAddedLines)
 *   appLines  จำนวนบรรทัดที่เปลี่ยนในไฟล์แอป
 *   isAgent   PR นี้มาจาก agent หรือเปล่า (ดูข้อจำกัดใน guard.mjs)
 *   gitignore เนื้อ .gitignore ฉบับใน PR นี้
 */
export function checkGuard(facts) {
  const f = facts || {};
  const changed = f.changed || [];
  const deleted = f.deleted || [];
  const added = f.added || [];
  const errors = [];
  const warnings = [];

  // ── 1. ใครก็ตามที่แตะ .github/ ต้องดังจนไม่มีทางพลาดตา ──────────
  // ไฟล์ในนั้นคือด่านตรวจเอง การแก้มันคือการแก้สิ่งที่ตรวจตัวเอง
  // agent ห้ามเด็ดขาด · เจ้าของห้ามไม่ได้ (ต้องแก้ workflow ของตัวเองเป็นปกติ)
  // จึงตะโกนแทน แล้วให้สายตาเจ้าของกับผู้ตรวจเป็นด่านจริง
  const gh = changed.filter(p => p.startsWith('.github/'));
  if (gh.length) {
    const list = gh.join(' · ');
    if (f.isAgent) errors.push(`PR ของ agent แก้ไฟล์ใน .github/ — ไม่อนุญาตเด็ดขาด (${list})`);
    else warnings.push(`PR ใบนี้แก้ไฟล์ด่านตรวจเอง (${list}) — ต้องอ่าน diff ส่วนนี้ด้วยตาก่อน merge ทุกครั้ง`);
  }

  // ── 2. secret หลุด (repo นี้เป็น public · INVARIANTS D1) ────────
  // ข้ามไฟล์ .md เพราะเอกสารพูดถึงรูปแบบของ token ได้โดยไม่ได้แปะตัวจริง
  for (const [re, what] of SECRET_PATTERNS) {
    const hit = added.find(a => !a.file.endsWith('.md') && re.test(a.text));
    if (hit) errors.push(`พบ ${what} ในบรรทัดที่เพิ่มเข้ามาที่ ${hit.file} — repo นี้เป็น public`);
  }

  // ── 3. รหัส PO ตัวจริง (INVARIANTS D1) ─────────────────────────
  // ตรวจรวมไฟล์ .md ด้วย ต่างจากข้อ 2 — เอกสารเป็นที่ที่รหัสจริงหลุดง่ายที่สุด
  // เพราะคนเขียนมักก๊อปมาจากของจริงเพื่อให้ "ตรงกับที่เห็นบนจอ"
  for (const a of added) {
    const m = REAL_PO_RE.exec(a.text);
    if (m) {
      errors.push(`พบรหัส PO ที่ขึ้นต้นด้วย TM ที่ ${a.file} (${m[0]}) — ` +
        'รหัสจริงของบริษัทห้ามอยู่ใน repo public · ตัวอย่างให้ใช้ ZZ หรือ XX แทน');
      break;
    }
  }

  // ── 4. ไฟล์ข้อมูลธุรกิจ ────────────────────────────────────────
  // ไฟล์ที่ถูก **ลบ** ไม่นับ — การเอาของที่ไม่ควรอยู่ออกไปคือสิ่งที่ด่านนี้ต้องการ
  const dataFiles = changed.filter(p => DATA_FILE_RE.test(p) && !deleted.includes(p));
  if (dataFiles.length) {
    errors.push(`PR นี้เพิ่มไฟล์ที่เป็นข้อมูลธุรกิจเข้ามา: ${dataFiles.join(' · ')} — ` +
      'ฟอร์มจริง ตารางที่ export มา และรูปจากหน้างาน ห้ามอยู่ใน repo นี้');
  }

  // ── 5. PR ของ agent ต้องเล็กพอที่จะรีวิวตอนพักเที่ยงได้ ─────────
  if (f.isAgent && Number(f.appLines) > APP_LINE_LIMIT) {
    errors.push(`PR จาก agent แก้ไฟล์แอปไป ${f.appLines} บรรทัด (เพดาน ${APP_LINE_LIMIT}) — ` +
      'ต้องหยุดถามเจ้าของก่อนแก้ใหญ่ขนาดนี้ แล้วแยกเป็นหลายใบ');
  }

  // ── 6. ของที่โหลดจากเน็ตต้องอยู่ในรายชื่อ และต้องปักรุ่น ────────
  // ⚠️ ตรวจเฉพาะไฟล์ที่ **เบราว์เซอร์โหลดจริง** เท่านั้น
  //    เอกสารต้องยกตัวอย่าง URL ที่ "ห้ามใช้" ได้ และไฟล์เทสต้องมีตัวอย่างโดเมนปลอม
  //    เพื่อพิสูจน์ว่าด่านนี้ยังจับได้ · ถ้าเหมารวม ด่านจะบล็อก PR ที่เพิ่มเทสของตัวเอง
  //    (เจอตอน dry-run ก่อน push ครั้งแรก — ด่านแดงใส่ไฟล์เทสของตัวเอง 7 ข้อ)
  for (const a of added.filter(x => isBrowserFile(x.file))) {
    for (const url of netLoadUrls(a.text)) {
      const host = hostOf(url);
      if (!ALLOWED_CDN_HOSTS.includes(host)) {
        errors.push(`${a.file} โหลดของจาก ${host} ซึ่งไม่อยู่ในรายชื่อที่อนุญาต ` +
          `(${ALLOWED_CDN_HOSTS.join(' · ')}) — เพิ่มโดเมนใหม่ต้องถามเจ้าของก่อน`);
      } else if (!PINNED_RE.test(url)) {
        errors.push(`${a.file} โหลด ${url} โดยไม่ได้ปักเลขรุ่นเป๊ะ — ` +
          'URL แบบนี้เปลี่ยนของใต้เท้าเราได้เองเงียบ ๆ ต้องระบุรุ่นเต็มเช่น 3.4.21');
      }
    }
  }

  // ── 7. ห้ามลบเทสทิ้งทั้งไฟล์ ────────────────────────────────────
  const delTests = deleted.filter(p => p.startsWith('tests/'));
  if (delTests.length) {
    errors.push(`PR นี้ลบไฟล์เทสทิ้ง: ${delTests.join(' · ')} — ` +
      'เทสแดงแปลว่าโค้ดผิด ไม่ใช่เทสผิด');
  }

  // ── 8. .gitignore ต้องยังปฏิเสธทุกอย่างก่อน ────────────────────
  // ถ้าบรรทัด `/*` หายไป ไฟล์ที่ไม่มีใครคิดถึงจะเริ่มถูกติดตามโดยไม่มีใครรู้
  // และอาการคือ "git add แล้วมันขึ้น" ซึ่งดูเหมือนปกติทุกอย่าง
  if (f.gitignore != null && !/^\/\*\s*$/m.test(txt(f.gitignore))) {
    errors.push('.gitignore ไม่มีบรรทัด `/*` ที่ปฏิเสธทุกอย่างก่อนแล้ว — ' +
      'repo นี้เป็น public ไฟล์ที่ไม่ได้อนุญาตไว้ต้องเพิ่มเข้ามาไม่ได้');
  }

  // ข้อความซ้ำไม่ได้ช่วยอะไร — บรรทัด CDN ที่ผิดแบบเดียวกันหลายบรรทัดควรขึ้นครั้งเดียว
  return { errors: [...new Set(errors)], warnings: [...new Set(warnings)] };
}
